-- =====================================================================
-- Mise à jour n°11 du 04/11/2026 : rattachement des parcours PAO aux sous-profils (à lancer APRÈS la n°10)
--   - 7 sous-profils PAO et PAO & IA : les parcours deviennent l'offre principale (pourquoi + argumentaire détaillé)
--   - les formations seules certifiantes passent en « Formations complémentaires »
-- À coller dans Supabase › SQL Editor › New query, puis « Run » (sans rien sélectionner).
-- Ne supprime aucune formation. Un sous-profil qui contient déjà un parcours PAO n'est pas modifié :
-- le relancer ne change rien. Les textes déjà modifiés dans Gestion pour les formations conservées sont gardés.
-- =====================================================================
update public.profils p set data = p.data
    || jsonb_build_object('parcours', (
         select jsonb_agg(
                  case when coalesce((t.x->>'force')::boolean, false) then coalesce(cur.e, '{}'::jsonb) || jsonb_build_object('formation', t.x->>'formation', 'pourquoi', t.x->>'pourquoi')
                       else coalesce(cur.e, t.x) end order by t.o)
         from jsonb_array_elements(v.pc) with ordinality as t(x, o)
         left join lateral (select e from jsonb_array_elements(p.data->'parcours') as y(e) where y.e->>'formation' = t.x->>'formation' limit 1) as cur(e) on true))
    || jsonb_build_object('complements', (
         select jsonb_agg(coalesce(cur.e, t.x) order by t.o)
         from jsonb_array_elements(v.cp) with ordinality as t(x, o)
         left join lateral (select e from jsonb_array_elements(coalesce(p.data->'complements', '[]'::jsonb)) as y(e) where y.e->>'formation' = t.x->>'formation' limit 1) as cur(e) on true)),
  updated_at = now()
from (values
  ('pao-001', $j$[{"formation": "pao-p-indesign", "pourquoi": "Le plus adapté : créer ses plaquettes, affiches et publications de A à Z.", "argumentaire": "Photoshop pour préparer et retoucher les images, puis InDesign pour monter les plaquettes, affiches et documents imprimés. La personne repart en sachant produire seule un support complet, prêt pour l'imprimeur ou le web. Certification Tosa InDesign pour valoriser la compétence."}, {"formation": "pao-p-ia", "pourquoi": "À proposer si elle produit surtout des visuels et veut gagner du temps grâce à l'IA d'Adobe.", "argumentaire": "Photoshop pour maîtriser la retouche et la composition d'images, puis Adobe & IA pour produire plus vite avec les outils IA intégrés (remplissage génératif, variantes, détourage). Idéal pour multiplier les visuels pour le web et les réseaux. Certification Tosa Photoshop."}, {"formation": "pao-p-illustrator", "pourquoi": "À proposer pour créer logos, pictogrammes et illustrations vectorielles.", "argumentaire": "Photoshop pour les images, Illustrator pour les éléments vectoriels nets à toutes les tailles : logos, pictos, infographies. Utile quand la structure gère sa propre identité visuelle. Certification Tosa Illustrator."}]$j$::jsonb, $j$[{"formation": "pao-indesign", "pourquoi": "InDesign seul : si elle maîtrise déjà Photoshop, ou pour un financement CPF par formation."}, {"formation": "pao-photoshop-init", "pourquoi": "Photoshop seul : pour un financement CPF par formation (certification Tosa)."}, {"formation": "pao-illustrator", "pourquoi": "Illustrator seul : si elle maîtrise déjà Photoshop, ou pour un financement CPF par formation."}, {"formation": "paoia-design", "pourquoi": "Créer des visuels avec les outils IA du design (Midjourney, Ideogram)."}, {"formation": "com-canva-pro", "pourquoi": "Aller plus loin sur Canva : charte, vidéo, IA, automatisation."}]$j$::jsonb),
  ('pao-002', $j$[{"formation": "pao-p-photopro", "pourquoi": "Le plus adapté : toute la chaîne, de la prise de vue à l'image finalisée.", "argumentaire": "Prise de vue (exposition, lumière, cadrage), Lightroom pour trier et développer ses séries de façon homogène, Photoshop pour les retouches et compositions. Une méthode complète et professionnelle, de l'appareil à la livraison client. Certification Tosa Photoshop."}, {"formation": "pao-p-photo", "pourquoi": "À proposer s'il n'utilise pas Lightroom ou veut un parcours plus court.", "argumentaire": "Prise de vue maîtrisée puis retouche et valorisation des images dans Photoshop. Un jour de moins que Photo Pro, pour qui travaille image par image plutôt qu'en séries. Certification Tosa Photoshop."}]$j$::jsonb, $j$[{"formation": "pao-photoshop-perf", "pourquoi": "Pour les retouches avancées, s'il maîtrise déjà Photoshop."}, {"formation": "paoia-adobe", "pourquoi": "L'IA intégrée à Photoshop et Illustrator pour produire plus vite."}, {"formation": "video-premiere", "pourquoi": "Monter des vidéos professionnelles."}]$j$::jsonb),
  ('pao-003', $j$[{"formation": "pao-prise-vue"}, {"formation": "pao-p-photo", "pourquoi": "À proposer s'il veut aussi retoucher ses photos avec Photoshop et mobiliser son CPF.", "argumentaire": "Réussir ses photos de produits (lumière, cadrage, fond) puis les détourer et les retoucher dans Photoshop pour sa boutique en ligne et ses réseaux. La certification Tosa Photoshop permet le financement CPF du module Photoshop."}, {"formation": "pao-affinity"}]$j$::jsonb, $j$[{"formation": "pao-lightroom", "pourquoi": "Retoucher rapidement et de façon cohérente toute une série de photos produits."}, {"formation": "com-canva1", "pourquoi": "Créer ses visuels soi-même, sans compétences graphiques."}]$j$::jsonb),
  ('pao-004', $j$[{"formation": "pao-p-illustrator", "pourquoi": "Le plus adapté : les deux logiciels de base de la création graphique.", "argumentaire": "Photoshop pour l'image et Illustrator pour le vectoriel : le socle attendu dans les offres d'emploi de graphiste. Certification Tosa Illustrator à mettre sur son CV."}, {"formation": "pao-p-indesign", "pourquoi": "À proposer si elle vise la mise en page (édition, imprimerie, communication).", "argumentaire": "Photoshop pour l'image, InDesign pour la mise en page professionnelle de documents imprimés. Certification Tosa InDesign à valoriser auprès des recruteurs."}, {"formation": "pao-p-ia", "pourquoi": "À proposer pour ajouter l'IA d'Adobe à ses compétences.", "argumentaire": "Photoshop, puis les outils IA intégrés à la suite Adobe : une compétence de plus en plus demandée. Certification Tosa Photoshop."}]$j$::jsonb, $j$[{"formation": "pao-photoshop-init", "pourquoi": "Photoshop seul : pour un financement CPF par formation (une certification Tosa par logiciel)."}, {"formation": "pao-illustrator", "pourquoi": "Illustrator seul : pour un financement CPF par formation (une certification Tosa par logiciel)."}, {"formation": "pao-indesign", "pourquoi": "InDesign seul : pour un financement CPF par formation (une certification Tosa par logiciel)."}, {"formation": "paoia-design", "pourquoi": "Créer des visuels avec les outils IA du design (Midjourney, Ideogram)."}]$j$::jsonb),
  ('pao-006', $j$[{"formation": "pao-p-indesign", "pourquoi": "Le plus adapté : préparer les images et monter des documents prêts pour l'imprimeur.", "argumentaire": "Photoshop pour préparer les images (résolution, couleurs, détourage), InDesign pour monter catalogues, magazines et plaquettes conformes aux exigences de l'imprimeur. Certification Tosa InDesign."}, {"formation": "pao-p-illustrator", "pourquoi": "À proposer pour les logos et illustrations intégrés aux mises en page.", "argumentaire": "Photoshop et Illustrator pour produire soi-même les éléments graphiques (logos, pictos, plans) intégrés aux documents. Certification Tosa Illustrator."}]$j$::jsonb, $j$[{"formation": "pao-indesign", "pourquoi": "InDesign seul : s'il maîtrise déjà Photoshop."}, {"formation": "pao-photoshop-perf", "pourquoi": "Retouches avancées pour l'impression, s'il maîtrise déjà les bases de Photoshop."}, {"formation": "paoia-adobe", "pourquoi": "Gagner du temps grâce à l'IA intégrée aux logiciels Adobe."}]$j$::jsonb),
  ('paoia-001', $j$[{"formation": "paoia-p-creation", "pourquoi": "Le plus adapté : l'IA d'Adobe et les générateurs d'images IA.", "argumentaire": "Adobe & IA pour gagner du temps dans ses logiciels habituels, puis IA design graphique pour explorer Midjourney et Ideogram et trouver de nouvelles pistes créatives. Parcours non certifiant, hors CPF."}, {"formation": "paoia-adobe", "pourquoi": "À proposer s'il veut seulement l'IA intégrée à ses logiciels Adobe.", "force": true}]$j$::jsonb, $j$[{"formation": "paoia-design", "pourquoi": "Explorer les générateurs d'images IA (Midjourney, Ideogram)."}, {"formation": "pao-photoshop-perf", "pourquoi": "Retouches et compositions avancées."}, {"formation": "ia-graphiste", "pourquoi": "Parcours IA certifiant : textes et visuels avec les outils IA du design."}]$j$::jsonb),
  ('paoia-002', $j$[{"formation": "paoia-design"}, {"formation": "paoia-p-creation", "pourquoi": "À proposer s'il travaille aussi avec la suite Adobe.", "argumentaire": "IA design graphique pour créer des visuels originaux, Adobe & IA pour les retravailler et les décliner dans Photoshop et Illustrator. Parcours non certifiant, hors CPF."}]$j$::jsonb, $j$[{"formation": "paoia-adobe", "pourquoi": "L'IA intégrée à Photoshop et Illustrator, s'il travaille avec la suite Adobe."}, {"formation": "com-canva-pro", "pourquoi": "Aller plus loin sur Canva : charte, vidéo, IA, automatisation."}, {"formation": "video-ia-avatar", "pourquoi": "Produire des vidéos avec un avatar IA, sans se filmer."}, {"formation": "ia-graphiste", "pourquoi": "Parcours IA certifiant : textes et visuels de communication avec l'IA."}]$j$::jsonb)
) as v(id, pc, cp)
where p.id = v.id
  and not exists (select 1 from jsonb_array_elements(p.data->'parcours') e where e->>'formation' in ('pao-p-ia','pao-p-indesign','pao-p-illustrator','pao-p-photo','pao-p-photopro','paoia-p-creation'))
  and (select count(*) from public.formations where id in ('pao-p-ia','pao-p-indesign','pao-p-illustrator','pao-p-photo','pao-p-photopro','paoia-p-creation')) = 6;

-- Vérification : 7 sous-profils avec leurs parcours
select id, data->>'nom' as sous_profil,
       (select string_agg(e->>'formation', ' · ' order by o) from jsonb_array_elements(data->'parcours') with ordinality as t(e, o)) as parcours
from public.profils where id in ('pao-001', 'pao-002', 'pao-003', 'pao-004', 'pao-006', 'paoia-001', 'paoia-002') order by id;
